package com.bct.ngtpa.apiservice.application.dto.session.authenticated;import java.time.*;import java.util.Objects;public record StoreAuthenticatedSessionCommand(AuthenticatedSessionId authenticatedSessionId,ProtectedAuthenticatedSession protectedSession,Duration ttl,Instant recordedAt,String correlationId){public StoreAuthenticatedSessionCommand{Objects.requireNonNull(authenticatedSessionId);Objects.requireNonNull(protectedSession);Objects.requireNonNull(ttl);Objects.requireNonNull(recordedAt);if(ttl.isZero()||ttl.isNegative())throw new IllegalArgumentException("ttl must be positive");correlationId=optional(correlationId);}private static String optional(String v){return v==null||v.isBlank()?null:v.trim();}@Override public String toString(){return "StoreAuthenticatedSessionCommand[id=<redacted>, protectedSession=<redacted>, ttl="+ttl+", recordedAt="+recordedAt+", correlationId="+correlationId+"]";}}
